use vstd::prelude::*;

verus! {

fn nanmin(a: Vec<i8>) -> (result: i8)
    requires
        a.len() > 0,
    ensures
        // result is some element of the array
        exists|k: int| 0 <= k < a.len() && result == a[k],
        // result is <= every element
        forall|k: int| 0 <= k < a.len() ==> result <= a[k],
{
    let mut minv: i8 = a[0];
    let mut i: usize = 1;

    while i < a.len()
        invariant
            1 <= i <= a.len(),
            // minv is an element among a[0..i)
            exists|k: int| 0 <= k < i && minv == a[k],
            // minv is <= all elements among a[0..i)
            forall|k: int| 0 <= k < i ==> minv <= a[k],
        decreases a.len() - i
    {
        let v = a[i];
        if v < minv {
            minv = v;
        }
        i += 1;
    }

    result = minv;

    // Postconditions follow from the loop invariants at i == a.len().
}

} // verus!